package owl.nh;

import com.google.gson.GsonBuilder;
import java.awt.*;
import java.awt.event.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import javax.swing.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

/** Local, explicit-save run recorder. It observes manual play and never sends gameplay input. */
final class AdminRecorderWindow extends JFrame {
 private static final int MAX_FRAMES=18000,MAX_EVENTS=30000,MAX_MARKERS=1000;
 private final Client client;private final ClientThread thread;private final EventBus bus;private final Path root;
 private final AdminZoomController zoom;private final List<Map<String,Object>> frames=new ArrayList<>(),events=new ArrayList<>(),markers=new ArrayList<>();
 private final Set<Projectile> seen=Collections.newSetFromMap(new IdentityHashMap<>());private final JComboBox<String> folders=new JComboBox<>(),outcome=new JComboBox<>(new String[]{"Unspecified","Completed","Failed","Stopped manually"});
 private final JLabel path=new JLabel(),status=new JLabel("Ready. Create or select a content folder."),counts=new JLabel();private final JTextField marker=new JTextField();private final JCheckBox extendedZoom=new JCheckBox("Extended zoom (loaded scene only)");
 private final javax.swing.Timer refresh;private volatile boolean recording,saving,closed;private int lastTick=-1;

 AdminRecorderWindow(Client client,ClientThread thread,EventBus bus,Path projectRoot){super("Turbo Admin Tool · Run Recorder");this.client=client;this.thread=thread;this.bus=bus;root=projectRoot.toAbsolutePath().normalize().resolve("recordings");zoom=new AdminZoomController(client,thread);buildUi();bus.register(this);refresh=new javax.swing.Timer(250,e->{counts.setText(summary());path.setText("Save root: "+root);});refresh.start();reloadFolders();}
 private void buildUi(){setDefaultCloseOperation(WindowConstants.HIDE_ON_CLOSE);setMinimumSize(new Dimension(700,420));setSize(780,500);setLocationByPlatform(true);JPanel body=new JPanel(new BorderLayout(10,10));body.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));setContentPane(body);JLabel heading=new JLabel("Rune run recorder");heading.setFont(heading.getFont().deriveFont(Font.BOLD,19f));body.add(heading,BorderLayout.NORTH);
  JTextArea info=new JTextArea("Record a manual run, add optional mechanic markers, then explicitly save it into a named content folder.\nLater you can provide that folder path for offline analysis. Chat, player names and credentials are not recorded.\nThe recorder observes only; it never performs gameplay actions.");info.setEditable(false);info.setOpaque(false);info.setLineWrap(true);info.setWrapStyleWord(true);JPanel center=new JPanel();center.setLayout(new BoxLayout(center,BoxLayout.Y_AXIS));center.add(info);center.add(Box.createVerticalStrut(12));center.add(status);center.add(counts);center.add(path);body.add(center,BorderLayout.CENTER);
  JPanel controls=new JPanel(new GridLayout(0,1,7,7));JPanel folderRow=new JPanel(new BorderLayout(7,0));folderRow.add(new JLabel("Content folder"),BorderLayout.WEST);folderRow.add(folders,BorderLayout.CENTER);JButton create=new JButton("New folder…"),open=new JButton("Open recordings folder");JPanel folderButtons=new JPanel(new GridLayout(1,2,7,0));folderButtons.add(create);folderButtons.add(open);folderRow.add(folderButtons,BorderLayout.EAST);controls.add(folderRow);
  JPanel run=new JPanel(new GridLayout(1,4,7,0));JButton start=new JButton("Record"),stop=new JButton("Stop"),save=new JButton("Save recording"),discard=new JButton("Discard");run.add(start);run.add(stop);run.add(save);run.add(discard);controls.add(run);
  JPanel markRow=new JPanel(new BorderLayout(7,0));marker.setToolTipText("Optional mechanic, phase or decision note (1–1000 characters)");markRow.add(marker,BorderLayout.CENTER);JButton mark=new JButton("Add marker");markRow.add(mark,BorderLayout.EAST);controls.add(markRow);JPanel options=new JPanel(new GridLayout(1,2,7,0));options.add(outcome);options.add(extendedZoom);controls.add(options);body.add(controls,BorderLayout.SOUTH);
  create.addActionListener(e->createFolder());open.addActionListener(e->openRoot());start.addActionListener(e->thread.invoke(()->{try{start();}catch(RuntimeException x){status.setText(x.getMessage());}}));stop.addActionListener(e->stop("Recording stopped"));save.addActionListener(e->save());discard.addActionListener(e->discardWithConfirmation());mark.addActionListener(e->thread.invoke(()->{try{addMarker(marker.getText());SwingUtilities.invokeLater(()->marker.setText(""));}catch(RuntimeException x){status.setText(x.getMessage());}}));extendedZoom.addActionListener(e->{if(extendedZoom.isSelected()){if(client.getGameState()!=GameState.LOGGED_IN){extendedZoom.setSelected(false);status.setText("Log into Orion before enabling extended zoom.");}else{zoom.enable();status.setText("Extended zoom enabled for the already-loaded scene.");}}else{zoom.disable();status.setText("Camera settings restored.");}});addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){stop("Admin Tool hidden");extendedZoom.setSelected(false);zoom.disable();}});
 }
 private synchronized String summary(){return "Recording: "+recording+" · ticks: "+frames.size()+" · events/actions: "+events.size()+" · markers: "+markers.size();}
 private synchronized void start(){if(closed||saving)throw new IllegalStateException("Wait for the current operation to finish.");if(recording)throw new IllegalStateException("Recording is already active.");if(!frames.isEmpty()||!events.isEmpty())throw new IllegalStateException("Save or discard the previous recording first.");if(folders.getSelectedItem()==null)throw new IllegalStateException("Create or select a content folder first.");if(client.getGameState()!=GameState.LOGGED_IN||client.getLocalPlayer()==null)throw new IllegalStateException("Log into Orion before recording.");lastTick=-1;seen.clear();recording=true;status.setText("Recording manual play into memory. Press Stop before saving.");}
 synchronized void stop(String reason){if(recording){recording=false;status.setText(reason+". Choose an outcome and Save recording.");}}
 private synchronized void discard(){recording=false;frames.clear();events.clear();markers.clear();seen.clear();lastTick=-1;status.setText("Unsaved recording discarded.");}
 private void discardWithConfirmation(){if(JOptionPane.showConfirmDialog(this,"Discard the unsaved recording?","Discard",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)discard();}
 private synchronized void addMarker(String value){if(!recording)throw new IllegalStateException("Start recording before adding a marker.");String clean=value==null?"":value.trim();if(clean.isEmpty()||clean.length()>1000)throw new IllegalArgumentException("Use a marker of 1–1000 characters.");if(markers.size()>=MAX_MARKERS)throw new IllegalStateException("Marker limit reached.");Map<String,Object> m=new LinkedHashMap<>();m.put("tick",client.getTickCount());m.put("cycle",client.getGameCycle());m.put("note",clean);markers.add(m);status.setText("Marker added.");}
 private static int[] items(ItemContainer container){if(container==null)return new int[0];Item[] source=container.getItems();int[] out=new int[source.length*2];for(int i=0;i<source.length;i++)if(source[i]!=null){out[i*2]=source[i].getId();out[i*2+1]=source[i].getQuantity();}return out;}

 @Subscribe public void onGameTick(GameTick ignored){zoom.pulse();synchronized(this){if(!recording)return;if(client.getGameState()!=GameState.LOGGED_IN||client.getLocalPlayer()==null){stop("Logout or loading observed");return;}if(frames.size()>=MAX_FRAMES){stop("Recording limit reached");return;}int tick=client.getTickCount();if(tick==lastTick)return;lastTick=tick;Player self=client.getLocalPlayer();WorldPoint position=self.getWorldLocation();Map<String,Object> f=new LinkedHashMap<>();f.put("tick",tick);f.put("cycle",client.getGameCycle());f.put("sceneBase",new int[]{client.getBaseX(),client.getBaseY()});f.put("position",new int[]{position.getX(),position.getY(),position.getPlane()});f.put("hp",client.getBoostedSkillLevel(Skill.HITPOINTS));f.put("prayer",client.getBoostedSkillLevel(Skill.PRAYER));f.put("animation",self.getAnimation());f.put("graphic",self.getGraphic());f.put("inventory",items(client.getItemContainer(InventoryID.INVENTORY)));f.put("equipment",items(client.getItemContainer(InventoryID.EQUIPMENT)));List<int[]> nearby=new ArrayList<>();for(NPC npc:client.getNpcs())if(npc.getWorldLocation().distanceTo(position)<=40&&nearby.size()<140)nearby.add(new int[]{npc.getId(),npc.getIndex(),npc.getWorldLocation().getX(),npc.getWorldLocation().getY(),npc.getWorldLocation().getPlane(),npc.getAnimation(),npc.getGraphic(),npc.getHealthRatio(),npc.getHealthScale()});f.put("npcs",nearby);List<int[]> projectiles=new ArrayList<>();if(client.getProjectiles()!=null)for(Projectile p:client.getProjectiles())if(projectiles.size()<160)projectiles.add(new int[]{p.getId(),p.getStartCycle(),p.getEndCycle(),p.getFloor(),p.getTarget()==null?-1:p.getTarget().getX(),p.getTarget()==null?-1:p.getTarget().getY()});f.put("projectiles",projectiles);List<int[]> graphics=new ArrayList<>();if(client.getGraphicsObjects()!=null)for(GraphicsObject g:client.getGraphicsObjects())if(!g.finished()&&g.getLevel()==client.getPlane()&&graphics.size()<160){WorldPoint p=WorldPoint.fromLocal(client,g.getLocation());if(p!=null&&p.distanceTo(position)<=40)graphics.add(new int[]{g.getId(),p.getX(),p.getY(),p.getPlane()});}f.put("graphics",graphics);List<String> prayers=new ArrayList<>();for(Prayer prayer:Prayer.values())if(client.isPrayerActive(prayer))prayers.add(prayer.name());f.put("activePrayers",prayers);frames.add(f);}}
 @Subscribe public synchronized void onProjectileMoved(ProjectileMoved e){if(!recording||events.size()>=MAX_EVENTS)return;Projectile p=e.getProjectile();seen.removeIf(old->old.getEndCycle()<client.getGameCycle());if(p==null||seen.contains(p)||seen.size()>=512)return;seen.add(p);Map<String,Object> d=event("PROJECTILE");d.put("id",p.getId());d.put("startCycle",p.getStartCycle());d.put("endCycle",p.getEndCycle());d.put("floor",p.getFloor());if(p.getTarget()!=null)d.put("targetLocal",new int[]{p.getTarget().getX(),p.getTarget().getY()});events.add(d);}
 @Subscribe public synchronized void onAnimationChanged(AnimationChanged e){actor(e.getActor(),"ANIMATION");}
 @Subscribe public synchronized void onGraphicChanged(GraphicChanged e){actor(e.getActor(),"GRAPHIC");}
 private void actor(Actor actor,String kind){if(!recording||actor==null||events.size()>=MAX_EVENTS||actor!=client.getLocalPlayer()&&!(actor instanceof NPC))return;Map<String,Object> d=event(kind);d.put("ownerNpcId",actor instanceof NPC?((NPC)actor).getId():-1);d.put("id",kind.equals("ANIMATION")?actor.getAnimation():actor.getGraphic());events.add(d);}
 @Subscribe public synchronized void onMenuOptionClicked(MenuOptionClicked e){if(!recording||events.size()>=MAX_EVENTS)return;String type=e.getMenuAction().name();if(type.contains("PLAYER")||!(type.startsWith("NPC_")||type.startsWith("GAME_OBJECT_")||type.equals("WALK")||type.contains("WIDGET")||type.startsWith("CC_OP")))return;Map<String,Object> d=event("MENU_ACTION");d.put("action",type);d.put("option",e.getMenuOption());d.put("id",e.getId());d.put("param0",e.getParam0());d.put("param1",e.getParam1());d.put("itemId",e.getItemId());events.add(d);}
 private Map<String,Object> event(String type){Map<String,Object> d=new LinkedHashMap<>();d.put("type",type);d.put("tick",client.getTickCount());d.put("cycle",client.getGameCycle());return d;}

 private void createFolder(){String name=JOptionPane.showInputDialog(this,"Folder name (for example: Sol Heredit)","New content folder",JOptionPane.PLAIN_MESSAGE);if(name==null)return;try{Path folder=folder(name);Files.createDirectories(folder);reloadFolders();folders.setSelectedItem(folder.getFileName().toString());status.setText("Content folder ready: "+folder);}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Invalid folder",JOptionPane.ERROR_MESSAGE);}}
 private Path folder(String name){String clean=name==null?"":name.trim();if(clean.isEmpty()||clean.length()>80||clean.equals(".")||clean.equals("..")||clean.contains("/")||clean.contains("\\")||clean.contains(":"))throw new IllegalArgumentException("Use a simple folder name of 1–80 characters without path separators.");Path resolved=root.resolve(clean).normalize();if(!resolved.getParent().equals(root))throw new IllegalArgumentException("Folder must stay inside the recordings directory.");return resolved;}
 private void reloadFolders(){try{Files.createDirectories(root);List<String> names=new ArrayList<>();try(java.util.stream.Stream<Path> entries=Files.list(root)){entries.filter(Files::isDirectory).map(p->p.getFileName().toString()).sorted(String.CASE_INSENSITIVE_ORDER).forEach(names::add);}Object selected=folders.getSelectedItem();folders.removeAllItems();for(String name:names)folders.addItem(name);if(selected!=null)folders.setSelectedItem(selected);}catch(IOException e){status.setText("Could not open recordings directory: "+e.getMessage());}}
 private void openRoot(){try{Files.createDirectories(root);Desktop.getDesktop().open(root.toFile());}catch(Exception e){JOptionPane.showMessageDialog(this,"Recordings folder: "+root+"\n"+e.getMessage(),"Open folder",JOptionPane.ERROR_MESSAGE);}}
 private void save(){final String json;final Path target;synchronized(this){if(recording){status.setText("Stop recording before saving.");return;}if(frames.isEmpty()){status.setText("There is no recording to save.");return;}if(saving)return;Object selected=folders.getSelectedItem();if(selected==null){status.setText("Create or select a content folder first.");return;}Path content=folder(selected.toString());Map<String,Object> data=new LinkedHashMap<>();data.put("schema","turbo-run-recorder-v1");data.put("createdAt",Instant.now().toString());data.put("contentFolder",selected.toString());data.put("outcome",String.valueOf(outcome.getSelectedItem()));data.put("privacy","No chat, player names, credentials, or external upload");data.put("frames",frames);data.put("events",events);data.put("markers",markers);json=new GsonBuilder().setPrettyPrinting().create().toJson(data);target=content.resolve("run-"+DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss").withZone(java.time.ZoneOffset.UTC).format(Instant.now())+".json");saving=true;status.setText("Saving locally…");}CompletableFuture.runAsync(()->{Path temp=null;try{Files.createDirectories(target.getParent());temp=Files.createTempFile(target.getParent(),".run-",".tmp");Files.writeString(temp,json,StandardCharsets.UTF_8);try{Files.move(temp,target,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,target);}synchronized(this){frames.clear();events.clear();markers.clear();seen.clear();lastTick=-1;}status.setText("Saved: "+target);}catch(Exception e){status.setText("Save failed; recording remains in memory: "+e.getMessage());}finally{if(temp!=null)try{Files.deleteIfExists(temp);}catch(IOException ignored){}saving=false;}});}
 void close(){closed=true;stop("Admin Tool closed");zoom.disable();bus.unregister(this);synchronized(this){frames.clear();events.clear();markers.clear();seen.clear();}SwingUtilities.invokeLater(()->{refresh.stop();dispose();});}
}
